def resolve(path, cwd, links):
    MAX_LINKS = 8
    link_count = 0

    # Normalize the initial path
    if not path.startswith('/'):
        path = cwd + '/' + path

    # Split path into components
    components = path.split('/')

    # Start with root
    current = []

    for component in components:
        # Skip empty components and '.'
        if component == '' or component == '.':
            continue

        # Handle '..'
        if component == '..':
            if current:
                current.pop()
            continue

        # Append the component
        current.append(component)

        # Build the current path
        current_path = '/' + '/'.join(current)

        # Check if this path is a symlink
        while current_path in links:
            link_count += 1
            if link_count > MAX_LINKS:
                return None

            # Get the link target
            target = links[current_path]

            # If target is absolute, start over from root
            if target.startswith('/'):
                current = []
                target_components = target.split('/')[1:]  # Skip empty first element
            else:
                # Target is relative to the directory containing the link
                # Remove the last component from current to get the directory
                if current:
                    current.pop()
                target_components = target.split('/')

            # Process target components
            for target_comp in target_components:
                if target_comp == '' or target_comp == '.':
                    continue

                if target_comp == '..':
                    if current:
                        current.pop()
                    continue

                current.append(target_comp)
                current_path = '/' + '/'.join(current)

                # Check if new path is also a symlink
                if current_path in links:
                    break
            else:
                # No break occurred, we're done with this link
                break

    # Build final path
    if not current:
        return '/'

    return '/' + '/'.join(current)

